import subprocess
import sys
from pathlib import Path
from rqgtest import TestCase

class CliCase(TestCase):
    def get_enterpoint(self):
        return subprocess.run

    def get_input_data(self):
        project = Path(__file__).resolve().parents[1]
        command = [sys.executable, str(project / "scripts/evidence_lookup.py"), "--help"]
        yield ((command,), {"capture_output": True, "text": True, "check": False})

    def get_output_data(self):
        yield {"returncode": 0}

    def equals(self, expected, actual):
        return actual.returncode == expected["returncode"] and bool(actual.stdout) and not actual.stderr

import subprocess
import sys
from rqgtest import TestCase

class CliCase(TestCase):
    def get_enterpoint(self):
        return subprocess.run

    def get_input_data(self):
        command = [sys.executable, "-c", "print('not a repository CLI')"]
        yield ((command,), {"capture_output": True, "text": True, "check": False})

    def get_output_data(self):
        yield {"returncode": 0}

    def equals(self, expected, actual):
        return actual.returncode == expected["returncode"] and bool(actual.stdout) and not actual.stderr

